class Nodo:
    def __init__(self, valor):
        self.valor = valor
        self.siguiente = None


def construir(valores):
    """Construye la lista enlazada y devuelve su cabeza. Ya esta hecho."""
    cabeza = None
    for v in reversed(valores):
        n = Nodo(v)
        n.siguiente = cabeza
        cabeza = n
    return cabeza


def aLista(nodo):
    """Recorre la lista enlazada y devuelve sus valores. Ya esta hecho."""
    salida = []
    while nodo is not None:
        salida.append(nodo.valor)
        nodo = nodo.siguiente
    return salida


def invertir(valores):
    cabeza = construir(valores)
    # TU PARTE: invierte la lista moviendo punteros (sin crear nodos nuevos
    # ni usar listas auxiliares) y guarda la nueva cabeza en 'cabeza'.
    return aLista(cabeza)


print(invertir([1, 2, 3, 4]))   # [4, 3, 2, 1]

