import java.util.*;

public class Main {

    static Nodo construir(int[] valores) {
        // Construye la lista enlazada y devuelve su cabeza. Ya esta hecho.
        Nodo cabeza = null;
        for (int i = valores.length - 1; i >= 0; i--) {
            Nodo n = new Nodo(valores[i]);
            n.siguiente = cabeza;
            cabeza = n;
        }
        return cabeza;
    }

    static int[] aLista(Nodo nodo) {
        // Recorre la lista enlazada y devuelve sus valores. Ya esta hecho.
        List<Integer> salida = new ArrayList<>();
        while (nodo != null) { salida.add(nodo.valor); nodo = nodo.siguiente; }
        int[] r = new int[salida.size()];
        for (int i = 0; i < r.length; i++) r[i] = salida.get(i);
        return r;
    }

    static int[] invertir(int[] valores) {
        Nodo cabeza = construir(valores);
        // TU PARTE: invierte la lista moviendo punteros (sin crear nodos nuevos
        // ni usar listas auxiliares) y guarda la nueva cabeza en 'cabeza'.
        return aLista(cabeza);
    }

    public static void main(String[] args) {
        System.out.println(Arrays.toString(invertir(new int[]{1, 2, 3, 4})));
    }
}

class Nodo {
    int valor;
    Nodo siguiente;
    Nodo(int valor) { this.valor = valor; }
}

