  // Monta el árbol a partir del array por niveles. Ya está hecho.
  if (niveles.length === 0 || niveles[0] === null) return null;
  const nodos = niveles.map(v => v === null ? null : new Nodo(v));
  for (let i = 0; i < nodos.length; i++) {
    if (nodos[i] === null) continue;
    if (2 * i + 1 < nodos.length) nodos[i].izq = nodos[2 * i + 1];
    if (2 * i + 2 < nodos.length) nodos[i].der = nodos[2 * i + 2];
  }
  return nodos[0];
}

function altura(niveles) {
  const raiz = construir(niveles);
  // Devuelve el número de nodos del camino más largo de la raíz a una hoja.
  // Un árbol vacío tiene altura 0; un árbol de un solo nodo, altura 1.
  return 0;
}

